package server

import (
	"bytes"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"strings"
	"sync"
	"testing"

	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

func newTestHandler(t *testing.T) (http.Handler, *store.Store) {
	t.Helper()
	s, err := store.Open(filepath.Join(t.TempDir(), "test.db"))
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = s.Close() })
	return NewHandler(s), s
}

func postJSON(t *testing.T, h http.Handler, url string, body any) (*httptest.ResponseRecorder, map[string]any) {
	t.Helper()
	var r *http.Request
	switch b := body.(type) {
	case string:
		r = httptest.NewRequest(http.MethodPost, url, strings.NewReader(b))
	case []byte:
		r = httptest.NewRequest(http.MethodPost, url, bytes.NewReader(b))
	default:
		raw, _ := json.Marshal(b)
		r = httptest.NewRequest(http.MethodPost, url, bytes.NewReader(raw))
	}
	if body != nil {
		r.Header.Set("Content-Type", "application/json")
	}
	w := httptest.NewRecorder()
	h.ServeHTTP(w, r)
	var decoded map[string]any
	if w.Body.Len() > 0 {
		_ = json.Unmarshal(w.Body.Bytes(), &decoded)
	}
	return w, decoded
}

func doRequest(t *testing.T, h http.Handler, method, url string) (*httptest.ResponseRecorder, map[string]any) {
	t.Helper()
	w := httptest.NewRecorder()
	h.ServeHTTP(w, httptest.NewRequest(method, url, nil))
	var decoded map[string]any
	if w.Body.Len() > 0 {
		_ = json.Unmarshal(w.Body.Bytes(), &decoded)
	}
	return w, decoded
}

func TestHealth(t *testing.T) {
	h, _ := newTestHandler(t)
	w, body := doRequest(t, h, http.MethodGet, "/healthz")
	if w.Code != http.StatusOK {
		t.Fatalf("status = %d, want %d", w.Code, http.StatusOK)
	}
	if got := w.Header().Get("Content-Type"); got != "application/json" {
		t.Fatalf("content type = %q", got)
	}
	if body["status"] != "ok" {
		t.Fatalf("body = %s", w.Body.String())
	}
}

func TestPostValidBatch(t *testing.T) {
	h, _ := newTestHandler(t)
	w, body := postJSON(t, h, "/v1/documents/doc1/changes", map[string]any{
		"deviceId": "dev-A",
		"changes": []map[string]any{
			{"id": "c1", "payload": map[string]any{"text": "hello"}},
			{"id": "c2", "payload": []any{1, 2, 3}},
		},
	})
	if w.Code != http.StatusOK {
		t.Fatalf("status = %d body = %s", w.Code, w.Body.String())
	}
	results, ok := body["results"].([]any)
	if !ok || len(results) != 2 {
		t.Fatalf("results = %v", body["results"])
	}
	r0 := results[0].(map[string]any)
	if r0["id"] != "c1" || r0["created"] != true || r0["cursor"].(float64) != 1 {
		t.Fatalf("r0 = %v", r0)
	}
	r1 := results[1].(map[string]any)
	if r1["id"] != "c2" || r1["cursor"].(float64) != 2 {
		t.Fatalf("r1 = %v", r1)
	}
}

func TestPostRejectsBadInput(t *testing.T) {
	h, s := newTestHandler(t)
	url := "/v1/documents/doc1/changes"
	seed := func() {
		if _, err := s.PostChanges("doc1", []store.Change{
			{ID: "existing", DeviceID: "dev", Payload: json.RawMessage(`{"v":1}`)},
		}); err != nil {
			t.Fatal(err)
		}
	}

	cases := []struct {
		name        string
		contentType string
		body        any
		seedFirst   bool
	}{
		{"wrong content type", "text/plain", `{"deviceId":"d","changes":[{"id":"a","payload":1}]}`, false},
		{"missing content type", "", `{"deviceId":"d","changes":[{"id":"a","payload":1}]}`, false},
		{"malformed json", "application/json", `{"deviceId":"d","changes":[`, false},
		{"trailing content", "application/json", `{"deviceId":"d","changes":[{"id":"a","payload":1}]}garbage`, false},
		{"empty deviceId", "application/json", map[string]any{"deviceId": "", "changes": []any{map[string]any{"id": "a", "payload": 1}}}, false},
		{"missing deviceId", "application/json", map[string]any{"changes": []any{map[string]any{"id": "a", "payload": 1}}}, false},
		{"empty changes", "application/json", map[string]any{"deviceId": "d", "changes": []any{}}, false},
		{"missing changes", "application/json", map[string]any{"deviceId": "d"}, false},
		{"empty id", "application/json", map[string]any{"deviceId": "d", "changes": []any{map[string]any{"id": "", "payload": 1}}}, false},
		{"missing payload", "application/json", map[string]any{"deviceId": "d", "changes": []any{map[string]any{"id": "a"}}}, false},
		{"null payload", "application/json", map[string]any{"deviceId": "d", "changes": []any{map[string]any{"id": "a", "payload": nil}}}, false},
		{"duplicate ids in batch", "application/json", map[string]any{"deviceId": "d", "changes": []any{
			map[string]any{"id": "a", "payload": 1},
			map[string]any{"id": "a", "payload": 2},
		}}, false},
		{"conflicting existing", "application/json", map[string]any{"deviceId": "d", "changes": []any{
			map[string]any{"id": "existing", "payload": 2},
		}}, true},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if tc.seedFirst {
				seed()
			}
			r := httptest.NewRequest(http.MethodPost, url, strings.NewReader(tc.body.(string)))
			if tc.contentType == "" {
				var raw map[string]any
				_ = json.Unmarshal([]byte(tc.body.(string)), &raw)
			}
			// Rebuild request honoring whether a Content-Type should be set.
			bodyStr := tc.body.(string)
			r = httptest.NewRequest(http.MethodPost, url, strings.NewReader(bodyStr))
			if tc.contentType != "" {
				r.Header.Set("Content-Type", tc.contentType)
			}
			w := httptest.NewRecorder()
			h.ServeHTTP(w, r)

			want := http.StatusBadRequest
			if tc.name == "conflicting existing" {
				want = http.StatusConflict
			}
			if w.Code != want {
				t.Fatalf("status = %d, want %d, body = %s", w.Code, want, w.Body.String())
			}
			if ct := w.Header().Get("Content-Type"); ct != "application/json" {
				t.Fatalf("error content type = %q", ct)
			}
			var errBody map[string]string
			if err := json.Unmarshal(w.Body.Bytes(), &errBody); err != nil || errBody["error"] == "" {
				t.Fatalf("error body = %s", w.Body.String())
			}
		})
	}
}

